use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::{Path,PathBuf},process::Command};
const R:&str="/home/ubuntu/src/zopro-perf-work/g1-columns176";const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-30-g1-columns176";
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn files(root:&Path,p:&Path,out:&mut Vec<PathBuf>){for e in fs::read_dir(p).unwrap(){let e=e.unwrap();let t=e.file_type().unwrap();assert!(!t.is_symlink());if t.is_dir(){files(root,&e.path(),out);}else{assert!(t.is_file());out.push(e.path().strip_prefix(root).unwrap().to_path_buf());}}}
fn main(){let r=Path::new(R);let d=Path::new(D);let review=r.join("archive-review");assert!(!review.exists());fs::create_dir(&review).unwrap();let mut summaries=vec![];
for name in["source-initial","source-fixed","receipts","workflow","codegen","stat"]{let to=review.join(name);fs::create_dir(&to).unwrap();assert!(Command::new("tar").arg("-xzf").arg(d.join(format!("artifacts/{name}.tar.gz"))).arg("-C").arg(&to).status().unwrap().success());let mut members=vec![];files(&to,&to,&mut members);for f in &members{assert_eq!(hash(to.join(f)),hash(r.join(f)));let s=f.to_string_lossy();assert!(!s.ends_with("-sdk")&&!s.ends_with(".words")&&!s.ends_with(".a1q")&&!s.ends_with(".expected"));}
if name.starts_with("source-"){assert_eq!(members.len(),178);let(tree,audit)=if name=="source-initial"{("source","source-audit.json")}else{("source-fixed","source-audit-fixed.json")};for(rel,h)in read(r.join(audit))["source_files_sha256"].as_object().unwrap(){assert_eq!(hash(to.join(tree).join(rel)),h.as_str().unwrap());}}
if name=="receipts"{assert_eq!(members.iter().filter(|p|p.starts_with("runs")&&p.file_name().unwrap()=="stdout.log").count(),216);assert!(to.join("decode-failed-access/stderr.log").exists());}
if name=="stat"{assert_eq!(members.len(),4);}summaries.push(json!({"archive":name,"regular_files_byte_exact":members.len()}));}
for n in["analysis.json","review.json","review.log","symbols.json","codegen.json","source-audit.json","source-audit-fixed.json","design.md","capture-design.md","repair.md","access-repair.md"]{assert_eq!(hash(d.join("artifacts").join(n)),hash(r.join(n)));}
let text=fs::read_to_string(d.join("README.md")).unwrap();let mut rest=text.as_str();let mut links=0;while let Some(i)=rest.find("]("){rest=&rest[i+2..];let end=rest.find(')').unwrap();let target=&rest[..end];if !target.starts_with("https://")&&!target.starts_with('#'){assert!(d.join(target).exists(),"{target}");links+=1;}rest=&rest[end+1..];}
let a=read(d.join("artifacts/analysis.json"));assert_eq!(a["caller_gate_passed"],false);let out=json!({"passed":true,"archives":summaries,"README_local_links_present":links,"private_inputs_and_executables_excluded":true,"failed_gate_preserved":true,"scope":"All six archives extracted and every member compared to retained originals;both178source maps verified;216successful raw command streams plus faileddecoder retained;no measurement or test rerun."});fs::write(d.join("artifacts/archive-review.json"),serde_json::to_vec_pretty(&out).unwrap()).unwrap();println!("Archive closure PASS;6archives byteexact/2×178source maps/216successfulstreams+faileddecoder/4counterCSVs;{links}links");}
